arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  /* Spacing (8px base) */
+  --space-1: 4px;
+  --space-2: 8px;
+  --space-3: 16px;
+  --space-4: 24px;
+  --space-5: 32px;
+  --space-6: 48px;
+  --space-7: 64px;
+  --space-8: 96px;
+
+  /* Radii */
+  --radius-sm: 10px;
+  --radius-md: 14px;
+  --radius-lg: 20px;
+  --radius-xl: 28px;
+
+  /* Shadows */
+  --shadow-sm: 0 1px 0 oklch(20% 0.01 210 / 0.06), 0 10px 24px oklch(20% 0.02 210 / 0.08);
+  --shadow-md: 0 1px 0 oklch(20% 0.01 210 / 0.08), 0 18px 50px oklch(20% 0.03 210 / 0.12);
+
+  /* OKLCH palette (warm + credible) */
+  --bg: oklch(98% 0.01 95);
+  --surface: oklch(99% 0.01 95);
+  --surface-2: oklch(97% 0.01 95);
+  --surface-3: oklch(95% 0.01 95);
+  --border: oklch(88% 0.02 200);
+
+  --text: oklch(20% 0.02 220);
+  --text-2: oklch(42% 0.02 220);
+  --text-3: oklch(55% 0.02 220);
+
+  --primary: oklch(54% 0.12 197);     /* soft teal */
+  --primary-2: oklch(44% 0.11 197);
+  --mint: oklch(92% 0.05 175);
+
+  --accent: oklch(70% 0.16 40);       /* amber */
+  --coral: oklch(68% 0.18 25);        /* coral for CTAs */
+
+  --focus: oklch(62% 0.18 200);
+
+  --container: 1200px;
+  --nav-h: 72px;
+}
+
+*{box-sizing:border-box}
+html{color-scheme:light}
+body{
+  margin:0;
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  line-height:1.5;
+  color:var(--text);
+  background:
+    radial-gradient(900px 450px at 15% -5%, oklch(92% 0.07 185 / 0.55), transparent 60%),
+    radial-gradient(900px 450px at 85% -10%, oklch(94% 0.06 45 / 0.35), transparent 55%),
+    var(--bg);
+}
+
+a{color:inherit; text-decoration:none}
+a:hover{text-decoration:underline}
+
+.container{max-width:var(--container); margin:0 auto; padding:0 var(--space-3)}
+
+/* Accessibility */
+:focus-visible{outline:2px solid var(--focus); outline-offset:3px}
+
+.skip-link{
+  position:absolute; left:-9999px; top:var(--space-3);
+  background:var(--surface);
+  border:1px solid var(--border);
+  padding:10px 12px;
+  border-radius:999px;
+  box-shadow:var(--shadow-sm);
+  z-index:9999;
+}
+.skip-link:focus{left:var(--space-3)}
+
+/* Top credibility ticker */
+.ticker{
+  background: linear-gradient(90deg, oklch(46% 0.10 197), oklch(52% 0.10 190));
+  color: oklch(98% 0.01 95);
+  border-bottom: 1px solid oklch(25% 0.02 210 / 0.15);
+}
+.ticker .inner{display:flex; gap:var(--space-3); align-items:center; padding:10px 0; overflow:hidden}
+.ticker .tag{
+  display:inline-flex; align-items:center; gap:10px;
+  font-weight:650; letter-spacing:0.2px;
+}
+.ticker .dot{width:8px; height:8px; border-radius:99px; background:var(--accent); box-shadow:0 0 0 3px oklch(75% 0.14 40 / 0.28)}
+.ticker .track{display:flex; align-items:center; gap:14px; white-space:nowrap}
+.ticker .stat{display:inline-flex; align-items:center; gap:10px; padding:6px 10px; border-radius:999px; background: oklch(98% 0.01 95 / 0.12); border:1px solid oklch(98% 0.01 95 / 0.18)}
+.ticker .stat svg{opacity:0.92}
+.ticker .mask{position:relative; overflow:hidden; flex:1}
+.ticker .mask:before, .ticker .mask:after{
+  content:"";
+  position:absolute;
+  top:0; bottom:0; width:80px; pointer-events:none;
+  z-index:2;
+}
+.ticker .mask:before{left:0; background:linear-gradient(90deg, oklch(46% 0.10 197) 25%, transparent)}
+.ticker .mask:after{right:0; background:linear-gradient(270deg, oklch(52% 0.10 190) 25%, transparent)}
+
+.ticker .marquee{display:flex; width:max-content; gap:14px; padding-left:10px; will-change:transform}
+@media (prefers-reduced-motion: reduce){
+  .ticker .marquee{transform:none !important}
+}
+
+/* Header / Nav */
+header{
+  position:sticky;
+  top:0;
+  z-index:50;
+  backdrop-filter:saturate(1.2) blur(10px);
+  background: oklch(98% 0.01 95 / 0.72);
+  border-bottom: 1px solid oklch(88% 0.02 200 / 0.65);
+}
+
+.nav{
+  height:var(--nav-h);
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:var(--space-3);
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap:12px;
+  min-width:max-content;
+}
+
+.logo{
+  width:40px; height:40px; border-radius:14px;
+  background: radial-gradient(circle at 30% 30%, oklch(80% 0.10 190), oklch(50% 0.12 197));
+  box-shadow: 0 10px 20px oklch(20% 0.03 220 / 0.10);
+  position:relative;
+}
+.logo:after{
+  content:"";
+  position:absolute;
+  inset:10px;
+  border-radius:999px;
+  border:2px solid oklch(98% 0.01 95 / 0.9);
+  box-shadow: inset 0 0 0 2px oklch(20% 0.03 220 / 0.06);
+}
+
+.brand .name{font-weight:800; letter-spacing:-0.3px}
+.brand .sub{font-size:12px; color:var(--text-2); margin-top:-2px}
+
+.nav-left{display:flex; align-items:center; gap:var(--space-4)}
+.nav-links{display:none; gap:6px; align-items:center}
+
+.nav-btn{
+  display:inline-flex; align-items:center; gap:10px;
+  padding:10px 12px;
+  border-radius:999px;
+  border:1px solid transparent;
+  background:transparent;
+  font:inherit;
+  color:var(--text);
+  cursor:pointer;
+}
+.nav-btn:hover{background: oklch(95% 0.01 95); border-color: oklch(88% 0.02 200)}
+.nav-btn[aria-expanded="true"]{background: oklch(92% 0.04 185 / 0.55); border-color: oklch(70% 0.08 190)}
+.nav-btn svg{opacity:0.75}
+
+.nav-actions{display:flex; align-items:center; gap:10px}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  padding:10px 14px;
+  border-radius:999px;
+  border:1px solid oklch(88% 0.02 200);
+  background:var(--surface);
+  font-weight:650;
+  cursor:pointer;
+}
+.btn:hover{box-shadow:var(--shadow-sm)}
+.btn.primary{
+  background: linear-gradient(180deg, oklch(58% 0.13 197), oklch(48% 0.12 197));
+  color: oklch(98% 0.01 95);
+  border-color: oklch(40% 0.08 197 / 0.6);
+}
+.btn.primary:hover{filter:saturate(1.05) brightness(1.02)}
+.btn.ghost{background:transparent}
+
+.icon-btn{
+  width:42px; height:42px;
+  border-radius:999px;
+  border:1px solid oklch(88% 0.02 200);
+  background:var(--surface);
+  display:grid; place-items:center;
+  cursor:pointer;
+}
+.icon-btn:hover{box-shadow:var(--shadow-sm)}
+
+/* Mega menu */
+.mega{
+  position:fixed;
+  inset: calc(var(--nav-h) + 44px) 0 auto 0; /* after ticker + nav */
+  z-index:60;
+  display:none;
+}
+
+.mega[aria-hidden="false"]{display:block}
+
+.mega .backdrop{
+  position:fixed;
+  inset:0;
+  background: oklch(20% 0.02 220 / 0.25);
+}
+
+.mega .panel{
+  position:relative;
+  margin:0 auto;
+  max-width: var(--container);
+  padding: var(--space-3);
+}
+
+.mega .card{
+  background: var(--surface);
+  border: 1px solid oklch(88% 0.02 200 / 0.9);
+  border-radius: var(--radius-xl);
+  box-shadow: var(--shadow-md);
+  padding: var(--space-4);
+  overflow:hidden;
+}
+
+.mega .grid{
+  display:grid;
+  grid-template-columns: 1.2fr 1fr;
+  gap: var(--space-4);
+}
+
+.mega .lead{
+  border-radius: var(--radius-lg);
+  padding: var(--space-4);
+  background:
+    radial-gradient(900px 450px at 20% 10%, oklch(92% 0.06 175 / 0.85), transparent 55%),
+    radial-gradient(900px 450px at 80% 20%, oklch(94% 0.06 40 / 0.55), transparent 55%),
+    oklch(97% 0.01 95);
+  border:1px solid oklch(88% 0.02 200 / 0.8);
+}
+
+.mega .lead h3{margin:0 0 8px 0; font-size:18px; letter-spacing:-0.2px}
+.mega .lead p{margin:0; color:var(--text-2)}
+
+.mega .cols{display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3)}
+.mega .col{padding:2px}
+.mega .col h4{margin:0 0 10px 0; font-size:13px; color:var(--text-2); text-transform:uppercase; letter-spacing:0.12em}
+.mega .link{
+  display:flex; align-items:center; justify-content:space-between;
+  gap:12px;
+  padding:10px 12px;
+  border-radius: 12px;
+  border: 1px solid transparent;
+}
+.mega .link:hover{
+  background: oklch(95% 0.02 180);
+  border-color: oklch(86% 0.04 180);
+  text-decoration:none;
+}
+.mega .link span{font-weight:650}
+.mega .pill{
+  font-size:12px;
+  padding:4px 8px;
+  border-radius:999px;
+  background: oklch(92% 0.04 185 / 0.65);
+  border:1px solid oklch(80% 0.06 185);
+  color: oklch(30% 0.05 190);
+}
+
+/* Mobile nav */
+.mobile-only{display:inline-flex}
+.desktop-only{display:none}
+
+.mobile-drawer{
+  position:fixed;
+  inset: 0 0 0 auto;
+  width:min(92vw, 420px);
+  background:var(--surface);
+  border-left:1px solid oklch(88% 0.02 200);
+  box-shadow: var(--shadow-md);
+  transform: translateX(102%);
+  transition: transform 220ms ease;
+  z-index:70;
+}
+.mobile-drawer[aria-hidden="false"]{transform: translateX(0)}
+.mobile-drawer .hd{display:flex; align-items:center; justify-content:space-between; padding:18px; border-bottom:1px solid var(--border)}
+.mobile-drawer .bd{padding:10px 18px 18px}
+.mobile-drawer details{border-bottom:1px solid oklch(88% 0.02 200 / 0.65); padding:10px 0}
+.mobile-drawer summary{list-style:none; cursor:pointer; font-weight:750; padding:8px 0}
+.mobile-drawer summary::-webkit-details-marker{display:none}
+.mobile-drawer a{display:block; padding:10px 10px; border-radius:12px}
+.mobile-drawer a:hover{background:var(--surface-2); text-decoration:none}
+.mobile-drawer .actions{display:grid; gap:10px; padding-top:14px}
+
+.drawer-backdrop{
+  position:fixed;
+  inset:0;
+  background: oklch(20% 0.02 220 / 0.25);
+  z-index:69;
+  display:none;
+}
+.drawer-backdrop[aria-hidden="false"]{display:block}
+
+/* Hero */
+main{padding-bottom:var(--space-8)}
+
+.hero{padding: var(--space-6) 0 var(--space-5)}
+.hero-grid{display:grid; gap: var(--space-4)}
+
+.hero-card{
+  border-radius: var(--radius-xl);
+  background: var(--surface);
+  border: 1px solid oklch(88% 0.02 200 / 0.9);
+  box-shadow: var(--shadow-md);
+  overflow:hidden;
+}
+
+.hero-inner{display:grid; gap: var(--space-4); padding: var(--space-5)}
+
+.kicker{display:inline-flex; align-items:center; gap:10px}
+.chip{font-size:12px; font-weight:750; letter-spacing:0.08em; text-transform:uppercase; padding:6px 10px; border-radius:999px; background: oklch(92% 0.06 185 / 0.7); border:1px solid oklch(80% 0.08 185); color: oklch(30% 0.06 190)}
+.badge{
+  display:inline-flex; align-items:center; gap:8px;
+  font-size:12px;
+  padding:6px 10px;
+  border-radius:999px;
+  background: oklch(97% 0.01 95);
+  border: 1px dashed oklch(78% 0.06 40);
+  color: var(--text-2);
+}
+
+.hero h1{margin:10px 0 0 0; font-size: clamp(30px, 4vw, 46px); line-height:1.08; letter-spacing:-0.8px}
+.hero p{margin:12px 0 0 0; color:var(--text-2); font-size: 17px; max-width: 64ch}
+
+.hero-actions{display:flex; flex-wrap:wrap; gap:12px; margin-top: var(--space-3)}
+
+.hero-media{
+  border-top:1px solid oklch(88% 0.02 200 / 0.65);
+  background:
+    radial-gradient(1100px 520px at 30% 20%, oklch(90% 0.07 175 / 0.9), transparent 55%),
+    radial-gradient(900px 450px at 80% 40%, oklch(92% 0.06 40 / 0.55), transparent 50%),
+    oklch(96% 0.01 95);
+  padding: var(--space-4);
+}
+
+.hero-illustration{
+  height: 260px;
+  border-radius: var(--radius-lg);
+  border: 1px solid oklch(88% 0.02 200 / 0.85);
+  background:
+    linear-gradient(180deg, oklch(98% 0.01 95 / 0.75), oklch(98% 0.01 95 / 0.35)),
+    radial-gradient(300px 220px at 30% 40%, oklch(75% 0.12 190 / 0.55), transparent 60%),
+    radial-gradient(260px 200px at 70% 55%, oklch(80% 0.14 45 / 0.45), transparent 65%),
+    radial-gradient(240px 200px at 55% 20%, oklch(78% 0.18 25 / 0.35), transparent 60%),
+    oklch(96% 0.01 95);
+  position:relative;
+  overflow:hidden;
+}
+
+.hero-illustration:before{
+  content:"";
+  position:absolute;
+  inset:0;
+  background: radial-gradient(700px 240px at 50% 95%, oklch(20% 0.02 220 / 0.10), transparent 60%);
+}
+
+.hero-illustration .floating{
+  position:absolute;
+  inset:auto;
+  padding: 10px 12px;
+  border-radius: 14px;
+  background: oklch(99% 0.01 95 / 0.92);
+  border: 1px solid oklch(88% 0.02 200 / 0.9);
+  box-shadow: var(--shadow-sm);
+  font-weight:650;
+  color: var(--text);
+}
+.hero-illustration .floating.small{font-size:12px; font-weight:700; color: var(--text-2)}
+
+.hero-illustration .f1{left:16px; top:18px}
+.hero-illustration .f2{right:16px; top:18px}
+.hero-illustration .f3{left:18px; bottom:18px}
+.hero-illustration .f4{right:18px; bottom:18px}
+
+/* Sections */
+.section{padding: var(--space-6) 0}
+.section.half{padding: var(--space-5) 0}
+.section .hd{display:flex; align-items:flex-end; justify-content:space-between; gap: var(--space-3); margin-bottom: var(--space-3)}
+.section h2{margin:0; font-size: 22px; letter-spacing:-0.3px}
+.section .sub{margin:6px 0 0 0; color:var(--text-2)}
+.section .viewall{font-weight:650; color: var(--primary-2)}
+
+.card{
+  background: var(--surface);
+  border: 1px solid oklch(88% 0.02 200 / 0.9);
+  border-radius: var(--radius-xl);
+  box-shadow: var(--shadow-sm);
+}
+
+/* Trending */
+.trend-grid{display:grid; gap: var(--space-3)}
+.trend-card{padding: var(--space-4)}
+.trend-list{display:grid; gap: 10px; margin-top: 12px}
+.trend-item{display:flex; align-items:flex-start; justify-content:space-between; gap: 14px; padding: 12px; border-radius: 16px; border:1px solid transparent}
+.trend-item:hover{border-color: oklch(86% 0.04 185); background: oklch(96% 0.02 180); text-decoration:none}
+.trend-item .meta{display:flex; flex-direction:column; gap:3px}
+.trend-item .cat{font-size:12px; font-weight:800; letter-spacing:0.10em; text-transform:uppercase; color: var(--text-3)}
+.trend-item .title{font-weight:750; letter-spacing:-0.2px}
+.trend-item .arrow{opacity:0.65}
+
+/* Newsletter CTA */
+.cta{
+  border-radius: var(--radius-xl);
+  border: 1px solid oklch(84% 0.06 190 / 0.55);
+  background:
+    radial-gradient(1200px 520px at 20% 0%, oklch(86% 0.10 185 / 0.65), transparent 55%),
+    radial-gradient(900px 450px at 85% 30%, oklch(90% 0.09 40 / 0.50), transparent 55%),
+    linear-gradient(180deg, oklch(97% 0.02 175), oklch(95% 0.02 175));
+  box-shadow: var(--shadow-md);
+  padding: var(--space-5);
+  display:grid;
+  gap: var(--space-4);
+}
+
+.cta h2{font-size: 26px; margin:0; letter-spacing:-0.4px}
+.cta p{margin: 8px 0 0 0; color: var(--text-2)}
+
+.form{
+  display:flex;
+  flex-wrap:wrap;
+  gap:10px;
+  align-items:center;
+}
+.input{
+  flex:1;
+  min-width: 220px;
+  border-radius: 999px;
+  border: 1px solid oklch(80% 0.06 185 / 0.8);
+  padding: 12px 14px;
+  background: oklch(99% 0.01 95 / 0.85);
+  font: inherit;
+}
+.privacy{font-size: 12px; color: var(--text-2)}
+
+.toast{
+  position:fixed;
+  inset:auto var(--space-3) var(--space-3) auto;
+  padding: 12px 14px;
+  border-radius: 16px;
+  background: oklch(18% 0.02 220 / 0.92);
+  color: oklch(98% 0.01 95);
+  border: 1px solid oklch(30% 0.02 220 / 0.25);
+  box-shadow: var(--shadow-md);
+  max-width: min(420px, calc(100vw - 24px));
+  transform: translateY(14px);
+  opacity:0;
+  pointer-events:none;
+  transition: transform 180ms ease, opacity 180ms ease;
+  z-index: 999;
+}
+.toast.show{transform: translateY(0); opacity:1}
+
+/* Topics carousel */
+.carousel-wrap{position:relative}
+.carousel{
+  display:flex;
+  gap: var(--space-3);
+  overflow:auto;
+  scroll-snap-type: x mandatory;
+  padding-bottom: 6px;
+  scrollbar-width: none;
+}
+.carousel::-webkit-scrollbar{display:none}
+
+.topic{
+  flex: 0 0 auto;
+  width: 170px;
+  scroll-snap-align: start;
+  padding: var(--space-3);
+  border-radius: var(--radius-xl);
+  border: 1px solid oklch(88% 0.02 200 / 0.9);
+  background: var(--surface);
+  box-shadow: var(--shadow-sm);
+}
+.topic:hover{transform: translateY(-2px); transition: transform 160ms ease}
+.topic .img{
+  width: 92px; height: 92px;
+  border-radius: 999px;
+  margin: 2px auto 12px;
+  border: 1px solid oklch(88% 0.02 200 / 0.85);
+  background:
+    radial-gradient(circle at 30% 25%, oklch(92% 0.06 175), transparent 60%),
+    radial-gradient(circle at 70% 75%, oklch(90% 0.10 40), transparent 60%),
+    radial-gradient(circle at 55% 40%, oklch(78% 0.18 25 / 0.35), transparent 60%),
+    oklch(96% 0.01 95);
+}
+.topic .label{font-weight:800; text-align:center; letter-spacing:-0.2px}
+.topic .desc{font-size: 13px; color: var(--text-2); text-align:center; margin-top: 6px}
+
+.car-btn{
+  position:absolute;
+  top: 42%;
+  transform: translateY(-50%);
+  width: 44px; height: 44px;
+  border-radius: 999px;
+  border: 1px solid oklch(88% 0.02 200);
+  background: oklch(99% 0.01 95 / 0.95);
+  box-shadow: var(--shadow-sm);
+  display:grid; place-items:center;
+  cursor:pointer;
+}
+.car-btn:hover{box-shadow: var(--shadow-md)}
+.car-btn.left{left:-10px}
+.car-btn.right{right:-10px}
+.car-btn:disabled{opacity:0.45; cursor:not-allowed}
+
+/* Tools */
+.tools-grid{display:grid; gap: var(--space-3)}
+.tools-split{display:grid; gap: var(--space-3)}
+
+.tools-hero{padding: var(--space-5)}
+.tools-hero h2{margin:0; font-size:24px; letter-spacing:-0.35px}
+.tools-hero p{margin:10px 0 0 0; color: var(--text-2)}
+.tools-hero .hero-actions{margin-top: var(--space-3)}
+
+.tool-list{display:grid; gap: 10px; margin-top: 14px}
+.tool-item{display:flex; align-items:flex-start; gap: 12px; padding: 12px; border-radius: 16px; border: 1px solid oklch(88% 0.02 200 / 0.65)}
+.tool-item:hover{background: oklch(96% 0.02 180); border-color: oklch(86% 0.04 185)}
+.tool-item .ic{
+  width: 36px; height: 36px;
+  border-radius: 12px;
+  background: oklch(92% 0.06 185 / 0.65);
+  border: 1px solid oklch(80% 0.07 185);
+  display:grid; place-items:center;
+  flex:0 0 auto;
+}
+.tool-item .txt{display:flex; flex-direction:column; gap:2px}
+.tool-item .txt strong{letter-spacing:-0.2px}
+.tool-item .txt span{color: var(--text-2); font-size: 13px}
+
+/* Recommended reads */
+.tabs{display:flex; flex-wrap:wrap; gap:10px}
+.tab{
+  padding:10px 12px;
+  border-radius: 999px;
+  border: 1px solid oklch(88% 0.02 200);
+  background: oklch(99% 0.01 95 / 0.85);
+  font-weight:750;
+  cursor:pointer;
+}
+.tab[aria-selected="true"]{background: oklch(92% 0.06 185 / 0.7); border-color: oklch(75% 0.08 185)}
+.tab:hover{box-shadow: var(--shadow-sm)}
+
+.article-grid{display:grid; gap: var(--space-3); margin-top: var(--space-3)}
+.article{
+  padding: var(--space-4);
+  display:flex;
+  flex-direction:column;
+  gap: 10px;
+}
+.article .top{display:flex; align-items:center; justify-content:space-between; gap: 12px}
