+  function step() {
+    const halfWidth = marquee.scrollWidth / 2;
+    x -= speed;
+    if (-x >= halfWidth) x = 0;
+    marquee.style.transform = `translate3d(${x}px, 0, 0)`;
+    requestAnimationFrame(step);
+  }
+
+  requestAnimationFrame(step);
+}
