+  }
+
+  left.addEventListener('click', () => scrollByCards(-1));
+  right.addEventListener('click', () => scrollByCards(1));
+  scroller.addEventListener('scroll', () => window.requestAnimationFrame(update));
+  window.addEventListener('resize', update);
+
+  update();
+}
+
